xml.Script:
        include 'Figures\Scripts\Cube_Standard_Colors.inc';

        SColors[ 0] := '     orbb          ';
        SColors[ 1] := '     rbwo          ';
        SColors[ 2] := '     wgrg          ';
        SColors[ 3] := '     yybr          ';
        SColors[ 4] := 'wgbr ggyw goww royg';
        SColors[ 5] := 'booy gyry rgrb wyby';
        SColors[ 6] := 'bbyr wygo ywrg rogo';
        SColors[ 7] := 'wgby borb yyrg yogb';
        SColors[ 8] := '     owwr          ';
        SColors[ 9] := '     rbwo          ';
        SColors[10] := '     wwob          ';
        SColors[11] := '     owgo          ';

        W := 0.5;

        N := 4;
        WD := W * 2 / N;
        D[0] := WD * (-N/2 + 1);
        for i := 1 to N - 2 do
            D[i] := D[i-1] + WD;

        DX := -0.03;
        DY := -0.06;
        DZ := -0.09;

        SColor := 'robgyw';
        function GetColor(X, Y);
        begin
            Result := -1;
            C := copy(SColors[N * SY + Y], ((N + 1) * SX + 1) + X, 1);
            i := Pos(C, SColor);
            if i > 0 then
                Result := Colors[i - 1];
        end;

